    const pPos = world.get(p.id, Position);
    if (!pPos) return;
    const status = findPetStatus();
    if (status.petAlive) return;
    if (status.petCorpseId > 0) {
      const petId = spawnResurrectedPetFromCorpse(status.petCorpseId, p.id, pPos);
      console.debug(`[settings] Resurrected pet ${petId}`);
      return;
    }
    for (const [petId] of world.query(Pet)) {
      if (world.has(petId, ItemInfo)) continue;
      const vit = world.get(petId, Vitality);
      if (!vit) continue;
      vit.hp = Math.max(1, Number(vit.maxHp || 1) | 0);
      if (world.has(petId, Position)) world.set(petId, Position, { x: pPos.x, y: pPos.y });
      else world.add(petId, Position, { x: pPos.x, y: pPos.y });
      console.debug(`[settings] Resurrected pet ${petId}`);
      break;
    }
  });

  addEventListener('ui:requestQuestJournalData', () => {
    const questMap = new Map();
    const playerId = Number(playerEntity(world)?.id || 0) | 0;
    for (const [, def, state, vars, bindings] of world.query(QuestDefRef, QuestState, QuestVars, QuestBindings)) {
      if (Number(bindings?.player || 0) !== playerId) continue;
      if (vars?.data?.accepted === false) continue;
      const questDef = getQuestDef(def.id);
      const rewardText = questJournalRewardText(questDef, vars?.data, def.id);
      const completionText = questJournalCompletionText(state, vars?.data);
      const rec = {
        questId: String(def.id || ''),
        title: String(questDef?.title || def.id || ''),
        status: String(state.status || 'active'),
        node: String(state.node || ''),
        t0: Number(state.t0 || 0),
        summary: String(vars?.data?.objective || ''),
        flavorText: questJournalFlavorText(questDef, vars?.data, def.id),
        rewardText,
        rewardItems: listQuestRewardItems(questDef, vars?.data).map((item) => ({
          itemId: item.itemId,
          name: item.name,
          description: item.description,
          count: item.count,
          tooltip: item.tooltip,
        })),
        rewardGold: Math.max(0, Number(vars?.data?.rewardGold || questDef?.journal?.rewardGold || 0) | 0),
        completionText,
        progress: Math.max(0, Number(vars?.data?.progress || 0) | 0),
        target: Math.max(0, Number(vars?.data?.target || 0) | 0),
        checklist: Array.isArray(vars?.data?.checklist)
          ? vars.data.checklist.map((entry) => ({
            text: String(entry?.text || ''),
            done: !!entry?.done,
          }))
          : [],
      };
      const prev = questMap.get(rec.questId);
      if (!prev || rec.t0 >= prev.t0) questMap.set(rec.questId, rec);
    }
    const quests = Array.from(questMap.values()).sort((a, b) => a.t0 - b.t0 || a.title.localeCompare(b.title));
    _uiEventTarget.dispatchEvent(new CustomEvent('ui:questJournalData', { detail: { quests } }));
  });

  return { buildGroundPickupDetailAt };
}

/**
 * Normalize authored quest reward choices into one canonical shape.
 *
 * A choice may contain a single item (legacy rewardItemIds/rewardItems) or a
 * package of items. The latter keeps reward balance and presentation in the
 * quest definition instead of scattering grant logic through quest scripts.
 */
export function listQuestRewardOptions(questDef, vars = {}) {
  const authored = Array.isArray(vars?.rewardChoices)
    ? vars.rewardChoices
    : (Array.isArray(questDef?.journal?.rewardChoices) ? questDef.journal.rewardChoices : []);
  if (authored.length > 0) {
    return authored.map((choice, index) => {
      const items = Array.isArray(choice?.items)
        ? choice.items
        : (choice?.itemId ? [{ itemId: choice.itemId, count: choice.count }] : []);
      return {
        id: String(choice?.id || items[0]?.itemId || `choice_${index + 1}`),
        label: String(choice?.label || "").trim(),
        items: items
          .filter((item) => item?.itemId)
          .map((item) => ({
            itemId: String(item.itemId),
            count: Math.max(1, Number(item.count || 1) | 0),
          })),
      };
    }).filter((choice) => choice.items.length > 0);
  }

  const authoredItems = Array.isArray(questDef?.journal?.rewardItems)
    ? questDef.journal.rewardItems.filter((item) => item?.itemId)
    : [];
  const ids = authoredItems.length > 0
    ? authoredItems
    : (Array.isArray(questDef?.journal?.rewardItemIds)
      ? questDef.journal.rewardItemIds.map((itemId) => ({ itemId }))
      : []);
  return ids.map((item, index) => ({
    id: String(item.itemId || `choice_${index + 1}`),
    label: String(item.label || "").trim(),
    items: [{
      itemId: String(item.itemId),
      count: Math.max(1, Number(item.count || vars?.rewardItemCounts?.[item.itemId] || 1) | 0),
    }],
  }));
}

export function listQuestRewardItems(questDef, vars = {}) {
  return listQuestRewardOptions(questDef, vars).flatMap((choice) => choice.items);
}

export function listQuestRewardBonusItems(questDef, vars = {}) {
  const authored = Array.isArray(vars?.rewardBonusItems)
    ? vars.rewardBonusItems
    : (Array.isArray(questDef?.journal?.rewardBonusItems) ? questDef.journal.rewardBonusItems : []);
  return authored.filter((item) => item?.itemId).map((item) => ({
    itemId: String(item.itemId),
    count: Math.max(1, Number(item.count || 1) | 0),
    label: String(item.label || "").trim(),
  }));
}

export function selectedQuestRewardItemIds(questDef, vars, rewardId) {
  const selected = listQuestRewardOptions(questDef, vars)
    .find((choice) => choice.id === String(rewardId || "")
      || choice.items.some((item) => item.itemId === String(rewardId || "")));
  return selected ? selected.items.map((item) => item.itemId) : [];
}
