    onAction: typeof opts.onAction === "function" ? opts.onAction : undefined,
  });

  function getDepth() {
    for (const [, ds] of world.query(DungeonState)) {
      return Number(ds.currentDepth || 0) | 0;
    }
    return 0;
  }

